1	<script setup lang="ts">
2	/**
3	 * Desktop-local reminders (fixture only). Compact drawer rows under real tabs;
4	 * the picker offers preset times plus a `Custom` typed RFC3339 field. Presets
5	 * only fill the same `due` value the typed field fills, so `put` payloads,
6	 * request ids, revisions and exact-retry semantics are exactly the typed path.
7	 */
8	import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
9	import type { CancelReminder, ConversationRef, MailClient, PutReminder, Reminder, ReminderCondition, ReminderPhase } from '../lib/ipc/client';
10	import { toMailError } from '../lib/ipc/client';
11	import { fullDateLabel } from '../lib/browsing-dates';
12	import { reminderPresets, type ReminderPresets } from '../lib/reminder-presets';
13	import { useDrawerRows } from '../composables/useDrawerRows';
14	import FullDate from './FullDate.vue';
15	
16	type Destination = 'pending' | 'returned' | 'history';
17	const TABS: ReadonlyArray<{ id: Destination; label: string }> = [
18	  { id: 'pending', label: 'Pending' },
19	  { id: 'returned', label: 'Returned' },
20	  { id: 'history', label: 'History' },
21	];
22	const FIXTURE_DETAIL = 'This device, while running. Overdue work reconciles on launch. No execution while fully quit or on other devices. '
23	  + 'New incoming mail stays in Inbox. Return and Cancel restore only the original inbox messages; neither marks mail read.';
24	const PHASES: Record<ReminderPhase, { word: string; tone: 'warn' | 'fault' | 'calm' }> = {
25	  pending: { word: 'Pending', tone: 'calm' },
26	  removing: { word: 'Removing…', tone: 'warn' },
27	  returning: { word: 'Returning…', tone: 'warn' },
28	  returned: { word: 'Returned', tone: 'calm' },
29	  failed: { word: 'Failed', tone: 'fault' },
30	  cancelling: { word: 'Cancelling…', tone: 'warn' },
31	  cancelled: { word: 'Cancelled', tone: 'calm' },
32	  suppressed: { word: 'Suppressed', tone: 'calm' },
33	};
34	const props = defineProps<{ client: MailClient; target: ConversationRef | null; initialDestination?: 'pending' | 'returned' | 'history' }>();
35	const emit = defineEmits<{ open: [target: ConversationRef]; destinationChange: [destination: 'pending' | 'returned' | 'history'] }>();
36	const rows = ref<Reminder[]>([]);
37	const error = ref('');
38	const preparationError = ref('');
39	const preparationTarget = ref<ConversationRef | null>(null);
40	const busy = ref(false);
41	const loading = ref(true);
42	const source = ref<{ conversation: ConversationRef; sourceMessageId: string; revision: number | null; subject: string } | null>(null);
43	const due = ref('');
44	/** Preset times, computed when the picker opens (one stable set per open picker). */
45	const presets = ref<ReminderPresets>(reminderPresets(new Date()));
46	const customOpen = ref(false);
47	const someday = ref(false);
48	const condition = ref<ReminderCondition>('if_no_reply');
49	const destination = ref<Destination>(props.initialDestination ?? 'pending');
50	watch(destination, value => emit('destinationChange', value));
51	let retry: { action: () => Promise<unknown>; command?: PutReminder } | null = null;
52	let alive = true;
53	let generation = 0;
54	let editorGeneration = 0;
55	let unsubscribe: (() => void) | undefined;
56	function bucketOf(r: Reminder): Destination {
57	  return r.phase === 'returned' ? 'returned' : r.phase === 'suppressed' || r.phase === 'cancelled' ? 'history' : 'pending';
58	}
59	const displayed = computed(() => rows.value.filter(r => bucketOf(r) === destination.value));
60	/** Counts of the currently loaded rows per bucket (the same filter as `displayed`). */
61	const counts = computed<Record<Destination, number>>(() => {
62	  const result: Record<Destination, number> = { pending: 0, returned: 0, history: 0 };
63	  for (const r of rows.value) result[bucketOf(r)]++;
64	  return result;
65	});
66	const drawerRows = useDrawerRows({ keys: () => displayed.value.map(r => r.conversation.conversationId) });
67	
68	// ---- Tabs: their own arrow keys; rows use J/K/arrows (useDrawerRows) -------
69	function onTabKeydown(event: KeyboardEvent) {
70	  if (event.isComposing || event.keyCode === 229 || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return;
71	  const index = TABS.findIndex(tab => tab.id === destination.value);
72	  const last = TABS.length - 1;
73	  const next = event.key === 'ArrowRight' ? (index + 1) % TABS.length
74	    : event.key === 'ArrowLeft' ? (index + last) % TABS.length
75	      : event.key === 'Home' ? 0
76	        : event.key === 'End' ? last
77	          : null;
78	  if (next === null) return;
79	  event.preventDefault();
80	  destination.value = TABS[next]!.id;
81	  void nextTick(() => document.getElementById(`reminder-tab-${destination.value}`)?.focus());
82	}
83	async function refresh() {
84	  const token = ++generation;
85	  try {
86	    const result = await props.client.reminders!.list();
87	    if (alive && token === generation) { rows.value = result; loading.value = false; }
88	  } catch { if (alive && token === generation) { error.value = 'Could not load local reminders. Retry refresh.'; loading.value = false; } }
89	}
90	async function run(action: () => Promise<unknown>, command?: PutReminder) {
91	  if (busy.value) return;
92	  const token = editorGeneration;
93	  // Retain both the exact payload and its validation context after a lost ACK.
94	  busy.value = true; error.value = ''; retry = { action, command };
95	  try { await action(); if (alive && token === editorGeneration) { retry = null; source.value = null; await refresh(); } }
96	  catch (raw) {
97	    if (alive && token === editorGeneration) {
98	      const failure = toMailError(raw);
99	      if (failure.kind === 'invalid_request' && failure.field === 'dueAt') {
100	        retry = null;
101	        error.value = 'Choose a future RFC3339 time with seconds and Z or a numeric timezone offset. Local times and leap seconds are not supported.';
102	      } else if (failure.kind === 'invalid_request' && failure.field === 'sourceMessageId' && command?.expectedRevision === null) {
103	        retry = null; source.value = null;
104	        preparationTarget.value = { ...command.conversation };
105	        preparationError.value = 'This conversation has a newer message. Refresh the source, review it, then schedule again.';
106	      } else if (failure.kind === 'invalid_request' || failure.kind === 'not_found') {
107	        retry = null; source.value = null;
108	        error.value = 'This target or revision is no longer actionable. Refresh and choose the current reminder before editing.';
109	        await refresh();
110	      } else {
111	        error.value = 'Reminder change was not acknowledged. Retry the exact request, or refresh to inspect durable state. Stale revisions require refresh before editing.';
112	      }
113	    }
114	  }
115	  finally { if (alive && token === editorGeneration) busy.value = false; }
116	}
117	async function prepare(target: ConversationRef) {
118	  if (busy.value || retry) return;
119	  const token = ++editorGeneration;
120	  const requested = { ...target };
121	  preparationTarget.value = requested;
122	  source.value = null;
123	  busy.value = true;
124	  try {
125	    const conversation = await props.client.getConversation(requested);
126	    if (!alive || token !== editorGeneration) return;
127	    const latest = conversation.messages.at(-1);
128	    if (conversation.ref.accountId !== requested.accountId || conversation.ref.conversationId !== requested.conversationId || !latest) {
129	      preparationError.value = 'No current source message is available for this conversation. Retry preparation after it is available.';
130	      return;
131	    }
132	    if (conversation.retainedSnapshotAt || conversation.contextComplete === false) {
133	      preparationError.value = 'This conversation is retained or incomplete. A current conversation is required; retry preparation after it is available.';
134	      return;
135	    }
136	    source.value = { conversation: requested, sourceMessageId: latest.id, revision: null, subject: conversation.subject };
137	    presets.value = reminderPresets(new Date());
138	    preparationTarget.value = null;
139	    preparationError.value = '';
140	  } catch { if (alive && token === editorGeneration) preparationError.value = 'Could not load the current source message. Retry preparation for this conversation.'; }
141	  finally { if (alive && token === editorGeneration) busy.value = false; }
142	}
143	function dismissPicker() {
144	  editorGeneration++;
145	  busy.value = false; retry = null; source.value = null;
146	  preparationTarget.value = null; preparationError.value = '';
147	}
148	watch(() => [props.client, props.target?.accountId, props.target?.conversationId], () => {
149	  dismissPicker();
150	  if (props.target) void prepare(props.target);
151	});
152	function reschedule(r: Reminder) {
153	  dismissPicker(); error.value = '';
154	  source.value = { conversation: r.conversation, sourceMessageId: r.sourceMessageId, revision: r.revision, subject: r.subject };
155	  presets.value = reminderPresets(new Date());
156	  due.value = r.dueAt ?? ''; someday.value = r.dueAt === null; condition.value = r.condition;
157	  customOpen.value = false;
158	}
159	const presetList = computed(() => {
160	  const list: Array<{ id: string; label: string; at: string }> = [];
161	  if (presets.value.laterToday) list.push({ id: 'later', label: 'Later today', at: presets.value.laterToday });
162	  list.push({ id: 'tomorrow', label: 'Tomorrow', at: presets.value.tomorrow });
163	  list.push({ id: 'next-week', label: 'Next week', at: presets.value.nextWeek });
164	  return list;
165	});
166	/** A typed or saved time that is not a preset is never hidden: Custom opens by itself. */
167	const customForced = computed(() => !someday.value && due.value !== '' && !presetList.value.some(preset => preset.at === due.value));
168	const customShown = computed(() => customOpen.value || customForced.value);
169	function choosePreset(at: string) { due.value = at; someday.value = false; customOpen.value = false; }
170	function submit() {
171	  if (!source.value || retry) return;
172	  if (!someday.value && due.value.trim() === '') return;
173	  const command: PutReminder = { conversation: source.value.conversation, sourceMessageId: source.value.sourceMessageId, expectedRevision: source.value.revision, dueAt: someday.value ? null : due.value, condition: condition.value, requestId: crypto.randomUUID() };
174	  void run(() => props.client.reminders!.put(command), command);
175	}
176	function cancel(r: Reminder) {
177	  const command: CancelReminder = { conversation: r.conversation, expectedRevision: r.revision, requestId: crypto.randomUUID() };
178	  void run(() => props.client.reminders!.cancel(command));
179	}
180	onMounted(async () => {
181	  const token = editorGeneration;
182	  try {
183	    const stop = await props.client.subscribe(() => { void refresh(); });
184	    if (!alive) { stop(); return; }
185	    unsubscribe = stop;
186	  } catch { if (alive) error.value = 'Live updates unavailable. Refresh to inspect progress.'; }
187	  await refresh();
188	  if (alive && token === editorGeneration && props.target) await prepare(props.target);
189	});
190	onBeforeUnmount(() => { alive = false; generation++; editorGeneration++; unsubscribe?.(); });
191	</script>
192	
193	<template>
194	  <div class="reminders-panel" data-test="reminders-panel">
195	    <!-- Honest state, once: the fixture disclosure is visible; the rest is its title and hidden text. -->
196	    <p class="drawer-note" role="note" :title="FIXTURE_DETAIL">Synthetic fixture only<span class="visually-hidden"> · {{ FIXTURE_DETAIL }}</span></p>
197	    <p v-if="error" role="alert" class="drawer-alert">{{ error }}</p>
198	    <p v-if="preparationError" role="alert" class="drawer-alert">{{ preparationError }}</p>
199	    <div class="drawer-toolbar reminders-toolbar">
200	      <button v-if="preparationTarget" type="button" class="drawer-quiet" :disabled="busy || !!retry" @click="prepare(preparationTarget)">{{ busy ? 'Preparing current source…' : 'Retry preparation / refresh source' }}</button>
201	      <button type="button" class="drawer-quiet" :disabled="busy" @click="retry ? run(retry.action, retry.command) : refresh()">{{ retry ? 'Retry exact request' : 'Refresh reminders' }}</button>
202	      <button v-if="retry" type="button" class="drawer-quiet" :disabled="busy" @click="dismissPicker(); error = ''; refresh()">Inspect durable state</button>
203	    </div>
204	    <form
205	      v-if="source"
206	      class="reminder-form"
207	      data-test="reminder-form"
208	      :data-source-conversation="source.conversation.conversationId"
209	      :data-source-message="source.sourceMessageId"
210	      @submit.prevent="submit"
211	    >
212	      <h3 class="drawer-section-title">{{ source.revision === null ? 'Remind me' : 'Reschedule' }}</h3>
213	      <!-- The subject names the mail; the opaque ids stay in the title and data attributes. -->
214	      <p class="reminder-subject" :title="`Conversation ${source.conversation.conversationId} · source ${source.sourceMessageId}`">{{ source.subject || '(No subject)' }}</p>
215	      <fieldset class="reminder-fields" :disabled="busy || !!retry">
216	        <div class="reminder-presets" role="group" aria-label="Return time">
217	          <button
218	            v-for="preset in presetList"
219	            :key="preset.id"
220	            type="button"
221	            class="drawer-chip"
222	            :data-test="`reminder-preset-${preset.id}`"
223	            :aria-pressed="!someday && due === preset.at"
224	            :title="fullDateLabel(preset.at)"
225	            @click="choosePreset(preset.at)"
226	          >{{ preset.label }}</button>
227	          <label class="reminder-someday" title="Someday — no automatic return"><input v-model="someday" type="checkbox"> Someday</label>
228	          <button
229	            v-if="!someday"
230	            type="button"
231	            class="drawer-chip"
232	            data-test="reminder-custom"
233	            :aria-expanded="customShown"
234	            aria-controls="reminder-custom-field"
235	            :disabled="customForced"
236	            @click="customOpen = !customOpen"
237	          >Custom</button>
238	        </div>
239	        <div v-if="!someday && customShown" id="reminder-custom-field" class="reminder-custom">
240	          <label class="field-row"><span class="field-label reminder-label">Time with timezone offset</span>
241	            <input v-model="due" class="field-input" required type="text" placeholder="2030-11-03T09:00:00-05:00" aria-describedby="reminder-time-help">
242	          </label>
243	          <p id="reminder-time-help" class="drawer-note">Use RFC3339 with Z or a numeric offset. No ambiguous local times or automatic DST adjustment.</p>
244	        </div>
245	        <label class="field-row"><span class="field-label reminder-label">Return condition</span>
246	          <select v-model="condition" class="field-input"><option value="if_no_reply">If no reply (default)</option><option value="regardless">Regardless of reply</option></select>
247	        </label>
248	        <div class="reminder-actions">
249	          <button type="submit" class="drawer-primary" :disabled="!someday && due.trim() === ''">{{ source.revision === null ? 'Schedule and remove from Inbox' : 'Save new time' }}</button>
250	          <button type="button" class="drawer-quiet" @click="dismissPicker">Dismiss picker</button>
251	        </div>
252	      </fieldset>
253	    </form>
254	    <div class="reminder-tabs" role="tablist" aria-label="Reminder membership" @keydown="onTabKeydown">
255	      <button
256	        v-for="tab in TABS"
257	        :id="`reminder-tab-${tab.id}`"
258	        :key="tab.id"
259	        type="button"
260	        role="tab"
261	        class="reminder-tab"
262	        :data-test="`reminder-tab-${tab.id}`"
263	        :aria-selected="destination === tab.id"
264	        aria-controls="reminder-tabpanel"
265	        :tabindex="destination === tab.id ? 0 : -1"
266	        @click="destination = tab.id"
267	      >{{ tab.label }} <span class="reminder-tab-count">{{ counts[tab.id] }}</span></button>
268	    </div>
269	    <div id="reminder-tabpanel" role="tabpanel" :aria-labelledby="`reminder-tab-${destination}`">
270	      <p v-if="loading" class="drawer-note" role="status">Loading local reminders…</p>
271	      <p v-else-if="!displayed.length" class="drawer-note">No {{ destination }} reminders.</p>
272	      <ul class="drawer-rows" @keydown="drawerRows.onKeydown">
273	        <li v-for="r in displayed" :key="r.conversation.conversationId" class="reminder-row" :data-test="`reminder-row-${r.phase}`">
274	          <div class="drawer-row">
275	            <button
276	              type="button"
277	              class="drawer-row-main"
278	              v-bind="drawerRows.rowAttrs(r.conversation.conversationId)"
279	              :title="`Revision ${r.revision}`"
280	              @click="emit('open', r.conversation)"
281	            >
282	              <span class="visually-hidden">Open </span>
283	              <span class="drawer-subject drawer-strong">{{ r.subject || '(No subject)' }}</span>
284	            </button>
285	            <span class="drawer-row-trailing">
286	              <span class="drawer-date"><FullDate v-if="r.dueAt" :at="r.dueAt" /><template v-else>Someday</template></span>
287	              <span class="activity-status reminder-phase" :class="`tone-${PHASES[r.phase].tone}`" :data-test="`reminder-phase-${r.phase}`">{{ PHASES[r.phase].word }}</span>
288	            </span>
289	          </div>
290	          <div v-if="r.condition === 'regardless' || ['removing', 'pending', 'returning', 'failed'].includes(r.phase)" class="drawer-row-actions">
291	            <span v-if="r.condition === 'regardless'" class="drawer-note" data-test="reminder-condition">Returns regardless of reply</span>
292	            <button v-if="r.phase === 'pending'" type="button" class="drawer-quiet" :disabled="busy || !!retry" @click="reschedule(r)">Reschedule</button>
293	            <button
294	              v-if="['removing', 'pending', 'returning', 'failed'].includes(r.phase)"
295	              type="button"
296	              class="drawer-quiet"
297	              :aria-label="r.phase === 'failed' ? 'Cancel reminder and recover original inbox messages' : 'Cancel reminder and restore original inbox messages'"
298	              :title="r.phase === 'failed' ? 'Cancel / recover original inbox messages' : 'Cancel and restore original inbox messages'"
299	              :disabled="busy || !!retry"
300	              @click="cancel(r)"
301	            >Cancel reminder</button>
302	          </div>
303	          <p v-if="r.phase === 'failed'" class="drawer-note tone-fault">Removal or return failed, or a later mailbox action superseded this reminder. Cancel does not override newer triage.</p>
304	        </li>
305	      </ul>
306	    </div>
307	  </div>
308	</template>
309	
310	<style scoped>
311	.reminders-panel { display: flex; flex-direction: column; gap: 12px; overflow-wrap: anywhere; }
312	.reminder-form, .reminder-fields { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
313	.reminder-fields { border: 0; margin: 0; padding: 0; }
314	.reminder-subject { margin: 0; color: var(--text-primary); font-weight: var(--weight-strong); }
315	.reminder-presets { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
316	.reminder-someday { display: inline-flex; align-items: center; gap: 6px; padding: 4px 8px; }
317	.reminder-custom { display: flex; flex-direction: column; gap: 4px; }
318	.reminder-label { flex: 0 0 9rem; }
319	.reminder-actions { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
320	.reminder-tabs { display: flex; gap: 6px; }
321	.reminder-tab { background: transparent; color: var(--text-secondary); border: 0; border-radius: 4px; padding: 4px 8px; }
322	.reminder-tab[aria-selected='true'] { color: var(--text-primary); font-weight: var(--weight-strong); background: var(--focus-fill); }
323	.reminder-tab-count { color: var(--text-secondary); font-weight: var(--weight-regular); font-variant-numeric: tabular-nums; }
324	</style>
