1	/**
2	 * Shared keyboard model for the rows of a utility drawer (Activity, Drafts,
3	 * Reminders).
4	 *
5	 * One marker, one handler:
6	 * - A row is any focusable element that carries `data-drawer-row`. The primary
7	 *   action of a row is that element's native behaviour (rows are real buttons),
8	 *   so Enter and Space are never handled here.
9	 * - The container handler moves focus with ArrowDown/ArrowUp or J/K (any case),
10	 *   and jumps with Home/End. Movement stops at both ends and never wraps.
11	 * - Roving tabindex: the current row is the one Tab stop (`0`), every other row
12	 *   is `-1`, and the first row owns the stop while no row is current. Trailing
13	 *   action buttons are not rows: they keep native Tab and Enter, and stay
14	 *   Tab-reachable after their row.
15	 * - It ignores editable targets, IME composition, modifier keys (including
16	 *   Shift) and any target that is not itself a row marker, so a trailing button,
17	 *   a field or a tab never has its keys taken.
18	 * - Escape is not handled: the app owns it (it closes the drawer; in the drafts
19	 *   editor the editor's own close runs first).
20	 */
21	import { ref, type Ref } from 'vue';
22	
23	export interface DrawerRowsOptions {
24	  /** Row keys in render order; the first one owns the Tab stop when none is current. */
25	  keys: () => readonly string[];
26	  /** The remembered current row (for example a panel's last opened row). */
27	  initial?: () => string | null;
28	}
29	
30	export interface DrawerRows {
31	  /** The current row key, or null while none was focused. */
32	  active: Ref<string | null>;
33	  /** Attributes for one row element: marker, roving tabindex and focus tracking. */
34	  rowAttrs: (key: string) => { 'data-drawer-row': string; tabindex: 0 | -1; onFocus: () => void };
35	  /** Keydown handler for the rows' container. */
36	  onKeydown: (event: KeyboardEvent) => void;
37	}
38	
39	const ROW_SELECTOR = '[data-drawer-row]';
40	
41	function isEditable(el: HTMLElement): boolean {
42	  if (el.isContentEditable) return true;
43	  const tag = el.tagName;
44	  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
45	}
46	
47	function navigationTarget(key: string): 'next' | 'prev' | 'first' | 'last' | null {
48	  switch (key) {
49	    case 'ArrowDown': return 'next';
50	    case 'ArrowUp': return 'prev';
51	    case 'Home': return 'first';
52	    case 'End': return 'last';
53	    default: break;
54	  }
55	  const lower = key.length === 1 ? key.toLowerCase() : key;
56	  if (lower === 'j') return 'next';
57	  if (lower === 'k') return 'prev';
58	  return null;
59	}
60	
61	export function useDrawerRows(options: DrawerRowsOptions): DrawerRows {
62	  const active = ref<string | null>(options.initial?.() ?? null);
63	
64	  function currentKey(): string | null {
65	    const keys = options.keys();
66	    if (active.value !== null && keys.includes(active.value)) return active.value;
67	    return keys[0] ?? null;
68	  }
69	
70	  function rowAttrs(key: string): { 'data-drawer-row': string; tabindex: 0 | -1; onFocus: () => void } {
71	    return {
72	      'data-drawer-row': key,
73	      tabindex: currentKey() === key ? 0 : -1,
74	      onFocus: () => { active.value = key; },
75	    };
76	  }
77	
78	  function onKeydown(event: KeyboardEvent): void {
79	    if (event.defaultPrevented) return;
80	    if (event.isComposing || event.keyCode === 229) return;
81	    if (event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return;
82	    const container = event.currentTarget;
