* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

/*
 * Buttons (DESIGN.md "Buttons"). Zero-specificity defaults so every component
 * class (split tabs, rail and row glyphs, contact lines) keeps its own look.
 *
 * Ghost (the default, browsing shell): transparent, Paper White text, 4px
 * radius, 24px tall at the 12px shell size (4px block padding) so the hit
 * target matches the old bordered chip. Hover lifts to Lifted Charcoal.
 */
:where(button) {
  background: transparent;
  color: var(--text-primary);
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  font: inherit;
  cursor: pointer;
}

:where(button:not(:disabled):hover) {
  background: var(--surface-raised);
}

/* On the raised composer surfaces the ghost hover fill equals the card
   background, so it would be invisible; use the stronger fill there. */
:where(.compose-card, .reply-composer) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

:where(button:not(:disabled):active) {
  background: var(--focus-fill);
}

:where(button:disabled) {
  opacity: 0.45;
  cursor: default;
}

/*
 * Utility chip: a Lifted Charcoal fill with a 1px Seam border, only inside
 * utility drawers, the modal attachment chooser, recovery banners and the
 * synthetic workspace strip. Same 24px height as the ghost button.
 */
:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button) {
  background: var(--surface-raised);
  font-size: var(--type-body);
  color: var(--danger);
}

/* Ghost glyph button: Graphite at rest, Paper White on hover/focus. */
.header-glyph {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 4px;
  color: var(--icon-muted);
  cursor: pointer;
}

.header-glyph:hover:not(:disabled),
.header-glyph:focus-visible,
.header-glyph[aria-pressed='true'] {
  color: var(--text-primary);
}

.header-glyph:disabled {
  opacity: 0.45;
  cursor: default;
}

/* While the previous thread is held for a fast J/K swap the actions stay
   disabled (never actionable) but do not dim: dimming for under 120ms is a
   flicker. They dim only once the loading presentation shows. */
.header-glyph.header-glyph-held:disabled {
  opacity: 1;
}

.header-glyph-icon {
  width: 1rem;
  height: 1rem;
}

.header-menu {
  justify-self: start;
  margin-left: 7px;
}

.header-tabs {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  /* Room for the focus ring of the first tab inside the clipped line. */
  padding: 4px 4px 4px 0;
  margin: -4px 0;
}

.app-title,
.split-tab {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
}

.app-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.app-title-account {
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.split-nav {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
}

.split-tab {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 2px;
  color: var(--text-tertiary);
  white-space: nowrap;
  cursor: pointer;
}

.split-tab:hover,
.split-tab[aria-current='page'] {
  color: var(--text-primary);
}

.split-tab:focus-visible {
  outline-offset: 2px;
}

.split-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.split-count {
  flex: 0 0 auto;
  font-size: var(--type-count);
  line-height: 1;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

/* Active list filter, in words beside the tabs. */
.header-filter {
 * column's bottom dock, so showing or hiding them never moves a row; static
 * context lines (coverage, draft recovery) sit above the list.
 */
.recovery-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 0;
  padding: 6px 24px 6px 50px;
  font-size: var(--type-body);
}

.recovery-banner p {
  margin: 0;
}

.draft-close-recovery {
  color: var(--warning);
}

/* Inside surfaces that already carry their own inset. */
.account-gate .recovery-banner,
.reader-pane .recovery-banner {
  padding: 0 0 6px;
}

/* Loading and empty list states, and Load more, on the content inset. */
.list-state {
  margin: 0;
  padding: 10px 24px 10px 50px;
  max-width: calc(75ch + 74px);
  color: var(--text-secondary);
}

.list-state:focus {
  outline: none;
}

.list-state:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: -2px;
}

.list-more {
  flex: 0 0 auto;
  align-self: flex-start;
  margin: 6px 0 6px 42px;
  font-weight: var(--weight-strong);
}

  flex: 1;
  min-height: 0;
  position: relative;
}

.app-main > .rail {
  grid-column: 1;
  grid-row: 1 / -1;
}

.app-main > .app-header,
.app-main > .list-notices,
.app-main > .list-dock {
  grid-column: 2;
}

.app-main > .app-header { grid-row: 1; }
.app-main > .list-notices { grid-row: 2; min-width: 0; }
.app-main > .list-dock { grid-row: 4; }

.app-main > .central,
.app-main > .account-gate {
  grid-column: 2;
  grid-row: 3;
}

.app-main > .contact-column {
  grid-column: 3;
  grid-row: 1 / -1;
}

@media (min-width: 1000px) {
  .app-main {
    grid-template-columns: auto minmax(0, 1fr) var(--contact-width);
  }
}

.rail {
  /* 40px icon rail (DESIGN.md "Rail"). Fixed px so larger root fonts widen
     the list, never the rail. Above the row-actions popover (6), below the
     utility drawers (30), so the keyboard tooltip clears the list. */
  pointer-events: none;
}

.rail-spacer {
  flex: 1;
}

.central {
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/*
 * Contact context column (DESIGN.md "Contact Pane"): 272px on Deep Umber with
 * a 24px inset. The name is centered on the split-tab line and the email on
 * the first list line; recent cached mail runs at a 24px pitch. These pinned
 * lines apply to the wide column only; the narrow disclosure stacks them.
 */
.contact-column {
  border-left: 1px solid var(--divider);
  background: var(--surface-contact);
  overflow-y: auto;
  padding: 0 var(--contact-inset) var(--contact-inset);
  min-height: 0;
  min-width: 0;
}

.contact-identity {

/*
 * Drawer rows (DESIGN.md "Drawer Row"): the one anatomy shared by Activity,
 * Drafts, Reminders and Cached Trash. A 36px row on 12px type, separated by
 * rhythm alone (no borders). The text sits on the drawer's 24px content edge;
 * the Focus Stone fill reaches 6px past it, with a 4px radius. The primary
 * action is one real button (`.drawer-row-main`, marked `data-drawer-row` for
 * the shared roving keyboard model); quiet ghost buttons and one status word
 * sit in the trailing slot. Focus uses the standard 2px ring, never a lavender
 * bar: the row is not "the current row" of the list.
 */
.drawer-rows {
  list-style: none;
  margin: 0;
  padding: 0;
}

.drawer-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 36px;
  margin-inline: -6px;
  padding-inline: 6px;
  border-radius: 4px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  color: var(--text-primary);
}

.drawer-row:hover,
.drawer-row:has(:focus-visible) {
  background: var(--focus-fill);
}

.drawer-row-main {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  gap: 12px;
  min-width: 0;
  min-height: 36px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}

.drawer-row-trailing {
  display: flex;
  flex: none;
  align-items: center;
  gap: 6px;
}

.drawer-subject,
.drawer-sender {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.drawer-subject {
  flex: 1 1 auto;
}

.drawer-sender {
  flex: 0 1 9em;
  font-weight: var(--weight-strong);
}

.drawer-strong,
.activity-action {
  font-weight: var(--weight-strong);
}

.activity-action,
.drawer-date,
.drawer-flag {
  flex: none;
  white-space: nowrap;
}

.drawer-date,
.drawer-flag,
.drawer-empty {
  color: var(--text-secondary);
}

.drawer-date {
  font-variant-numeric: tabular-nums;
}

.activity-status {
  flex: none;
  white-space: nowrap;
}

/* Status colour lives on the word alone (Status-Is-Sacred: words, not tints). */
.tone-warn {
  color: var(--warning);
}

.tone-fault {
  color: var(--danger);
}

.activity-status.tone-calm {
  color: var(--text-secondary);
}

/* Lines under a row or a toolbar: Ash notes, Coral alerts, plain lines. */
.drawer-note,
.drawer-alert,
.drawer-line {
  margin: 0 0 6px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  overflow-wrap: anywhere;
}

.drawer-note {
  color: var(--text-secondary);
}

.drawer-alert {
  color: var(--danger);
}

.drawer-section {
  margin: 0 0 12px;
}

.drawer-section-title {
  margin: 0 0 6px;
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
}

.drawer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 0 6px;
}

.drawer-toolbar > .drawer-note {
  margin: 0;
}

.drawer-row-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0 0 6px;
}

/* Ghost buttons in a drawer: quiet Ash text, Paper White Title weight for the
   one action, Focus Stone for a choice. Their text lines up with the content
   edge; the 8px padding is only the hit target. */
.drawer-quiet,
.drawer-action,
.drawer-primary,
.drawer-chip {
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  background: transparent;
  font: inherit;
}

.drawer-quiet {
  color: var(--text-secondary);
}

.drawer-action {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-chip {
  color: var(--text-secondary);
}

.drawer-chip[aria-pressed='true'] {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary {
  background: var(--focus-fill);
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-quiet:hover:not(:disabled),
.drawer-action:hover:not(:disabled),
.drawer-chip:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary:hover:not(:disabled) {
  background: var(--focus-fill);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

/* On a hovered row the fill already equals the button hover fill: add the ring. */
.drawer-row .drawer-quiet:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--text-secondary);
