 */
.inbox-scroll {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  height: 100%;
  min-height: 0;
  /* Row columns size from the list width (cqi), never from one row's content. */
  container-type: inline-size;
}

/*
 * Flex (not grid) so the bounded trailing region cannot starve the subject.
 * The sender column is sized from the list width, so it stays aligned on
 * every row and gives up width first as the pane narrows: 132px from a
 * ~700px list, ~115px at the 1030px window, 96px at its floor. Only if a row
 * still cannot fit its subject/snippet floor does that row's sender shrink
 * further (to 72px); the metadata keeps its full content.
 */
.inbox-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 36px;
  margin: 0 6px;
  padding: 0 18px 0 44px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  color: var(--text-primary);
  cursor: pointer;
  /* Anchors the gutter controls and the row action disclosure panel. */
  position: relative;
}

.inbox-row:focus {
  outline: none;
}

/* Focus: Focus Stone fill plus a 4px Dusk Lavender bar on the fill's own edge. */
.inbox-row.focused {
  background: var(--focus-fill);
  box-shadow: inset 4px 0 0 var(--focus-accent);
}

/* Hover never changes focus or read state; it only lifts and reveals controls. */
.inbox-row:not(.focused):hover {
  background: rgba(255, 255, 255, 0.03);
}

/*
 * UX-05 selection: a distinct marker that is not color-only (the checked
 * checkbox stays rendered and the row carries an Ash inset bar), never
 * replacing the lavender focus bar, which stays on the focused row.
 */
.inbox-row.selected {
  box-shadow: inset 4px 0 0 var(--text-secondary);
}

.inbox-row.selected.focused {
  box-shadow: inset 4px 0 0 var(--focus-accent), inset 6px 0 0 var(--text-secondary);
}

/* Gutter checkbox: revealed by selection mode, hover, the focused row, or its own focus. */
.row-select {
  position: absolute;
  left: 12px;
  top: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0;
  appearance: none;
  background: transparent;
  border: 1px solid var(--text-secondary);
  left: 30.5px;
  width: 7px;
  height: 7px;
  margin-top: -3.5px;
  border: 1.5px solid var(--text-secondary);
}

.row-sender {
  flex: 0 1 clamp(96px, 22cqi - 22px, 132px);
  min-width: 72px;
  font-weight: var(--weight-strong);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Known-read rows step down a weight; unread and unknown keep the Title weight. */
.inbox-row.read-disclosed.is-read .row-sender {
  font-weight: var(--weight-regular);
}

.row-subject-snippet {
  flex: 1 1 0;
  /* Readable-subject floor: never collapses to zero, and never narrower than
     the subject's own floor plus the gap (larger user text), so the subject
     cannot spill over the pending/date metadata. */
  min-width: max(136px, calc(6.5rem + 12px));
  display: flex;
  gap: 12px;
  white-space: nowrap;
}

.row-subject {
  flex: 0 1 auto;
  min-width: 6.5rem; /* subject keeps a readable prefix even in the widest metadata case */
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-preview {
  flex: 1 1 40%; /* preview yields to the subject; it claims at most 40% first */
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-secondary);
}

.row-meta {
  flex: 0 0 auto; /* content-sized and never squeezed: no clipped actions */
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.row-pending {
  font-style: italic;
