/* Gutter checkbox: revealed by selection mode, hover, the focused row, or its own focus. */
.row-select {
  position: absolute;
  left: 12px;
  top: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0;
  appearance: none;
  background: transparent;
  border: 1px solid var(--text-secondary);
  left: 30.5px;
  width: 7px;
  height: 7px;
  margin-top: -3.5px;
  border: 1.5px solid var(--text-secondary);
}

.row-sender {
  flex: 0 1 clamp(96px, 22cqi - 22px, 132px);
  min-width: 72px;
  font-weight: var(--weight-strong);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Known-read rows step down a weight; unread and unknown keep the Title weight. */
.inbox-row.read-disclosed.is-read .row-sender {
  font-weight: var(--weight-regular);
}

.row-subject-snippet {
  flex: 1 1 0;
  /* Readable-subject floor: never collapses to zero, and never narrower than
     the subject's own floor plus the gap (larger user text), so the subject
     cannot spill over the pending/date metadata. */
  min-width: max(136px, calc(6.5rem + 12px));
  display: flex;
  gap: 12px;
  white-space: nowrap;
}

.row-subject {
  flex: 0 1 auto;
  min-width: 6.5rem; /* subject keeps a readable prefix even in the widest metadata case */
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-preview {
  flex: 1 1 40%; /* preview yields to the subject; it claims at most 40% first */
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-secondary);
}

.row-meta {
  flex: 0 0 auto; /* content-sized and never squeezed: no clipped actions */
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.row-pending {
  font-style: italic;
  color: var(--warning);
}

/*
 * P5a/P3: the attachment glyph sits before the date (DESIGN.md row spec) as a
 * Graphite (icon-muted) 16px paperclip in the metadata row; it replaces
 * nothing and is three-state like the read marker — solid when attachments
 * are known present, nothing when known absent.
 */
.row-attachment {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  color: var(--icon-muted);
}

/*
 * Unknown attachment state: same Graphite icon-muted color as the solid
 * glyph, but quieter (the glyph itself is a thin outline stroke, mirroring
 * the hollow unread ring), so "unknown" stays visible yet distinct from a
 * known paperclip.
