.row-attachment-unknown {
  opacity: 0.75;
}

/*
 * One trailing slot holds the date and the actions (or the compact disclosure
 * control) in the same grid cell, so revealing the glyphs on the focused or
 * hovered row replaces the date without shifting any column.
