    if (!live) return;
    live = false; session++; generation++;
    unsubscribe?.(); unsubscribe = undefined;
    dismissPicker();
    target.value = null;
  }
  onScopeDispose(deactivate);

  return {
    rows, error, preparationError, preparationTarget, busy, loading, source, due, presets, customOpen, someday, condition,
    destination, target, activeRow, retrying,
    displayed, counts, presetList, customForced, customShown,
    onTabKeydown, refresh, prepare, dismissPicker, setTarget, reschedule, choosePreset, submit, cancel, retryOrRefresh, inspectDurableState,
    activate, deactivate, whenLoaded: () => loaded,
  };
}

